  const el={list:document.querySelector('#strategy-list'),count:document.querySelector('#strategy-count'),today:document.querySelector('#today-view'),history:document.querySelector('#history-view'),cases:document.querySelector('#cases-view'),search:document.querySelector('#search-view'),input:document.querySelector('#search-input'),searchForm:document.querySelector('#search-form'),context:document.querySelector('.context'),calendarControl:document.querySelector('.calendar-control'),dateTrigger:document.querySelector('#date-calendar-trigger'),dateLabel:document.querySelector('#date-label'),calendar:document.querySelector('#date-calendar'),contextLabel:document.querySelector('#context-label'),contextCount:document.querySelector('#context-count'),toast:document.querySelector('#update-toast'),updatedMessage:document.querySelector('#update-updated'),checkedMessage:document.querySelector('#update-checked')};
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
