const inlineHistoryCalendar=()=>false;
function syncCalendarPresentation(){const target=el.context;if(el.calendarControl.parentElement!==target)target.append(el.calendarControl);el.calendarControl.classList.remove('is-inline','is-strategy-history');el.calendarControl.hidden=mode!=='history';el.dateTrigger.hidden=false;el.calendar.hidden=true;el.dateTrigger.setAttribute('aria-expanded','false')}
function bindDateControl(){el.dateTrigger.addEventListener('click',event=>{event.stopPropagation();el.calendar.hidden=!el.calendar.hidden;el.dateTrigger.setAttribute('aria-expanded',String(!el.calendar.hidden));if(!el.calendar.hidden)renderCalendar()});document.addEventListener('click',event=>{if(!el.calendar.contains(event.target)&&!el.dateTrigger.contains(event.target)){el.calendar.hidden=true;el.dateTrigger.setAttribute('aria-expanded','false')}})}
function today(){const active=doc();const list=entries();const title=selectedStrategy||'今日策略指引';el.contextLabel.textContent='今日策略';el.contextCount.textContent=`${list.length} 项原文`;el.today.innerHTML=`<header class="hero"><div><p>DAILY STRATEGY GUIDANCE</p><h1>${esc(title)} <time>${esc(active.date)}</time></h1><span>完整保留每条策略的原始指引</span></div><strong>${list.length}<small>项原文</small></strong></header><div class="entry-grid">${list.map(entryCard).join('')||'<p class="empty">此日暂无匹配策略。</p>'}</div>`}
function history(){el.contextLabel.textContent='历史回溯';if(selectedStrategy){const series=data.documents.filter(item=>item.entries.some(entry=>entry.strategy===selectedStrategy));el.contextCount.textContent=`${series.length} 份日表`;el.history.innerHTML=`<header class="page-title page-title-with-calendar"><div><p>HISTORY / TIMELINE</p><h1>${esc(selectedStrategy)} 历史原文</h1><span>${series.length} 份日表</span></div><div id="history-calendar-slot" aria-label="历史日表日历"></div></header><div class="timeline">${series.map(item=>`<article class="timeline-item" data-history-date="${item.dateKey}"><time class="timeline-date">${item.date}</time><div class="entry-grid">${item.entries.filter(entry=>entry.strategy===selectedStrategy).map(entryCard).join('')}</div></article>`).join('')}</div>`;return}const series=data.documents.filter(item=>item.entries.length);el.contextCount.textContent=`${series.length} 日已归档`;el.history.innerHTML=`<header class="page-title page-title-with-calendar"><div><p>HISTORY / BY DATE</p><h1>按日期回溯</h1><span>${series.length} 日已归档</span></div><div id="history-calendar-slot" aria-label="历史日表日历"></div></header><div class="reading"><div class="entry-grid">${entries().map(entryCard).join('')}</div></div>`}
function caseCard(item){const sections=[['背景','background'],['策略判断','judgement'],['执行动作','action'],['结果','result'],['复盘','review']].filter(([,key])=>item[key]);return `<article class="case-card" id="case-${esc(item.id)}"><span class="case-card-icon" style="--icon:url('${icon(iconFor(item.strategy))}')" aria-hidden="true"></span><div class="case-type">${esc(item.strategy)} <span>${esc(item.case_date)}</span></div><h3>${esc(item.title||'未命名案例')}</h3><div class="case-manager">${esc(item.manager)}</div><div class="case-fields">${sections.map(([label,key])=>`<section class="case-field"><div class="label">${label}</div><p>${esc(item[key])}</p></section>`).join('')}</div></article>`}
function renderCases(){if(window.__STRATEGY_CASES__===null){el.contextLabel.textContent='策略案例';el.contextCount.textContent='正在读取';el.cases.innerHTML='<div class="case-loading" role="status"><span class="case-loading-spinner"></span>正在读取案例</div><div class="case-loading-grid" aria-hidden="true"><div></div><div></div></div>';return}const all=window.__STRATEGY_CASES__||[],filtered=all.filter(item=>!selectedStrategy||item.strategy===selectedStrategy),managers=new Set(all.map(item=>String(item.manager||'').trim()).filter(Boolean));el.contextLabel.textContent='策略案例';el.contextCount.textContent=`${filtered.length} 个案例`;const notice=window.__STRATEGY_CASES_ERROR__?`<p class="case-search-unavailable">策略案例暂时无法读取，请稍后刷新重试。</p>`:'';el.cases.innerHTML=`<section class="case-hero"><p class="case-kicker">策略案例库 / MANAGER NOTES</p><h1>萃取、沉淀、迭代、精进</h1><div class="case-meta">这里展示由投资经理填写并发布的实践记录。每日原始策略观点仍以共享表格为准，案例内容是独立的补充档案。</div><div class="case-summary"><span><strong>${all.length}</strong>个案例</span><span><strong>${managers.size}</strong>位撰写者</span></div></section>${notice}<div class="case-grid">${filtered.map(caseCard).join('')||(!notice?'<p class="empty">暂无匹配的已发布案例。</p>':'')}</div>`}
function highlight(value,query){const safe=esc(value);if(!query)return safe;return safe.replace(new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'gi'),'<mark>$1</mark>')}
function search(query){const key=query.trim().toLocaleLowerCase();if(!key){show('today');return}show('search');const hits=[];data.documents.forEach(document=>document.entries.forEach(entry=>entry.cells.forEach(cell=>{const text=`${entry.strategy} ${fieldLabel(cell)} ${fieldText(cell)}`;if(text.toLocaleLowerCase().includes(key))hits.push({document,entry,cell})})));el.search.innerHTML=`<header class="page-title"><p>SEARCH / ORIGINAL TEXT</p><h1>“${esc(query)}”</h1><span>${hits.length} 条原文匹配</span></header><div class="results">${hits.slice(0,100).map((hit,index)=>`<button data-hit="${index}"><small>${hit.document.date} · ${esc(hit.entry.strategy)}</small><strong>${highlight(fieldLabel(hit.cell),query)}</strong><p>${highlight(fieldText(hit.cell),query)}</p></button>`).join('')||'<p class="empty">没有匹配结果。</p>'}</div>`;el.search.querySelectorAll('[data-hit]').forEach(button=>button.addEventListener('click',()=>{const hit=hits[Number(button.dataset.hit)];selectedDate=hit.document.dateKey;selectedStrategy=hit.entry.strategy;calendarMonth=selectedDate.slice(0,4);el.input.value='';show('today');render()}))}
function show(next){mode=next;saveView(next);document.title=`策略指引 · ${{history:'历史回溯',cases:'策略案例',search:'搜索',today:'今日指引'}[next]||'今日指引'}`;['today','history','cases','search'].forEach(name=>{el[name].hidden=name!==next});el.context.hidden=next==='search';document.querySelectorAll('.topbar nav a[href]').forEach(link=>{const active=({today:'/',history:'/archive',cases:'/cases'})[next]===link.getAttribute('href');link.classList.toggle('is-active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});document.querySelectorAll('[data-mode]').forEach(button=>button.classList.toggle('is-active',button.dataset.mode===next));if(next==='today')today();if(next==='history')history();if(next==='cases')renderCases();syncCalendarPresentation()}
function render(nextMode=mode){mode=nextMode;strategyList();el.dateLabel.textContent=doc()?.date||'选择日期';renderCalendar();show(nextMode)}
function formatUpdateTime(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return value.replace('T',' ').slice(0,16);return date.toLocaleString('zh-CN',{hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).replace(/\//g,'.')}
  function updateIndicator(state){const checking=Boolean(state?.inProgress),failed=state?.lastResult==='failed',updated=state?.lastResult==='updated',retryCount=Number(state?.retryCount||0),updatedAt=state?.updatedAt?formatUpdateTime(state.updatedAt):'暂无',checkedAt=state?.checkedAt?formatUpdateTime(state.checkedAt):'暂无';el.toast.classList.toggle('is-checking',checking);el.toast.classList.toggle('is-ready',!checking&&!failed);el.toast.classList.toggle('is-failed',failed);el.updatedMessage.textContent=`上次更新：${updatedAt}`;el.checkedMessage.textContent=checking?'上次检查：正在检查':failed?`上次检查：失败${retryCount?`，已重试 ${retryCount} 次`:''}`:`上次检查：${checkedAt}`;el.toast.title=`${el.updatedMessage.textContent}\n${el.checkedMessage.textContent}`}
async function checkUpdate(){if(window.__STRATEGY_UPDATE_STATUS__){updateIndicator(window.__STRATEGY_UPDATE_STATUS__);return}try{const response=await fetch('/api/update-status',{cache:'no-store'});if(!response.ok)throw new Error('status unavailable');updateIndicator(await response.json())}catch(_error){updateIndicator({inProgress:false,lastResult:'',updatedAt:''})}}
function start(payload){data=payload;selectedDate=data.documents[0]?.dateKey||'';calendarMonth=selectedDate.slice(0,4);const initialMode=savedView();el.input.addEventListener('input',event=>search(event.target.value));el.searchForm.addEventListener('submit',event=>{event.preventDefault();search(el.input.value)});document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();show(button.dataset.mode)}));document.querySelector('.brand')?.addEventListener('click',()=>saveView('today'));document.addEventListener('click',event=>{const monthButton=event.target.closest('[data-calendar-shift]');if(monthButton){event.preventDefault();event.stopImmediatePropagation();calendarMonth=shiftMonth(calendarMonth,Number(monthButton.dataset.calendarShift));renderCalendar();return}const dateButton=event.target.closest('[data-date]');if(!dateButton)return;event.preventDefault();const keepStrategy=mode==='history'&&Boolean(selectedStrategy);selectedDate=dateButton.dataset.date;if(!keepStrategy)selectedStrategy=null;calendarMonth=selectedDate.slice(0,4);el.calendar.hidden=true;el.dateTrigger.setAttribute('aria-expanded','false');render();if(keepStrategy)requestAnimationFrame(()=>document.querySelector(`[data-history-date="${selectedDate}"]`)?.scrollIntoView({behavior:'smooth',block:'start'}))});bindDateControl();render(initialMode);checkUpdate();if(!window.__STRATEGY_UPDATE_STATUS__)window.setInterval(checkUpdate,3000)}
const source=window.__STRATEGY_DATA__?Promise.resolve(window.__STRATEGY_DATA__):fetch('../site/site-data.json').then(response=>response.json());source.then(start).catch(error=>{el.today.textContent=`无法读取展示数据：${error.message}`});
// Case data is a separate editorial layer. Only published records reach this frame.
const strategyOriginalSearch=search;
search=function(query){
  strategyOriginalSearch(query);
  const key=query.trim().toLocaleLowerCase();
  if(!key)return;
  const cases=(window.__STRATEGY_CASES__||[]).filter(item=>[item.title,item.strategy,item.manager,item.background,item.judgement,item.action,item.result,item.review].some(value=>String(value||'').toLocaleLowerCase().includes(key)));
  if(!cases.length){
    if(window.__STRATEGY_CASES_ERROR__){const note=document.createElement('p');note.className='case-search-unavailable';note.textContent=`策略案例暂不可搜索：${window.__STRATEGY_CASES_ERROR__}`;el.search.querySelector('.results').after(note)}
    return;
  }
  const results=el.search.querySelector('.results');
  const noOriginal=results.querySelector('.empty');
  if(noOriginal)noOriginal.textContent='原始观点无匹配；下方有策略案例。';
  const section=document.createElement('section');section.className='case-search-group';
  section.innerHTML=`<h2>策略案例 <small>${cases.length} 条已发布匹配</small></h2>${cases.slice(0,50).map(item=>`<a class="case-search-hit" href="/cases?case=${encodeURIComponent(item.id)}"><small>${esc(item.case_date)} · ${esc(item.strategy)} · ${esc(item.manager)}</small><strong>${highlight(item.title,query)}</strong><p>${highlight([item.background,item.judgement,item.action,item.result,item.review].find(value=>String(value||'').toLocaleLowerCase().includes(key))||item.judgement,query)}</p></a>`).join('')}`;
  results.after(section);
  el.search.querySelector('.page-title span').textContent+=` · ${cases.length} 条案例匹配`;
};
document.querySelector('.brand')?.addEventListener('click',event=>{event.preventDefault();selectedStrategy=null;if(data)render('today')});
