// Keep the public shell mounted: route changes alter only the content view.
let requestedRoute=null;
function applyRoute(route){if(!route||!data){requestedRoute=route;return}requestedRoute=null;const next=['today','history','cases'].includes(route.view)?route.view:'today';const focused=String(route.case||'');if(next!==mode){selectedStrategy=null;render(next)}if(next==='cases'&&focused){const focusedCase=(window.__STRATEGY_CASES__||[]).find(item=>String(item.id)===focused);if(focusedCase&&selectedStrategy&&selectedStrategy!==focusedCase.strategy){selectedStrategy=null;render('cases')}requestAnimationFrame(()=>document.getElementById(`case-${focused}`)?.scrollIntoView({behavior:'smooth',block:'center'}))}if(route.q){el.input.value=route.q;search(route.q)}}
window.addEventListener('message',event=>{if(event.source!==window.parent||event.data?.type!=='strategy:route')return;applyRoute(event.data.route)});
window.addEventListener('message',event=>{if(event.source!==window.parent||event.data?.type!=='strategy:data')return;const payload=event.data.payload||{};const previous=JSON.stringify([window.__STRATEGY_CASES__,window.__STRATEGY_CASES_ERROR__]);window.__STRATEGY_CASES__=Array.isArray(payload.cases)?payload.cases:[];window.__STRATEGY_CASES_ERROR__=payload.error||'';window.__STRATEGY_UPDATE_STATUS__=payload.status||{};updateIndicator(window.__STRATEGY_UPDATE_STATUS__);if(previous!==JSON.stringify([window.__STRATEGY_CASES__,window.__STRATEGY_CASES_ERROR__])){source.then(()=>{if(mode==='cases'){strategyList();renderCases()}else if(mode==='search'&&el.input.value)search(el.input.value)})}});
source.then(()=>{if(requestedRoute)applyRoute(requestedRoute)});
document.addEventListener('click',event=>{if(!window.__STRATEGY_DATA__)return;const link=event.target.closest('.topbar a[href], .case-search-hit[href]');if(!link||link.target==='_blank')return;const path=link.getAttribute('href');const destination={"/":"today","/archive":"history","/cases":"cases"}[path?.split('?')[0]];if(!destination)return;event.preventDefault();event.stopImmediatePropagation();if(destination!==mode){selectedStrategy=null;render(destination)}const focused=path?.startsWith('/cases?')?new URLSearchParams(path.split('?')[1]).get('case'):'';if(focused)applyRoute({view:'cases',case:focused});window.parent.postMessage({type:'strategy:navigate',path},'*')},true);
